SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT 

        WHERE b.IS_DELETED = 0
         AND b.ORDER_ID    = #{orderId} 
         AND b.ITEM_TYPE   = #{itemType} 
         AND b.OPERATOR_ID = #{operatorId} 
         AND b.RECORD_TIME >= #{startDate} 
         AND b.RECORD_TIME <  #{endDate} 
        ORDER BY b.RECORD_TIME DESC, b.ITEM_ID DESC
    ) t WHERE ROWNUM <= #{offset} + #{limit}
) WHERE rn > #{offset}

SELECT COUNT(1) FROM BILL_ITEM b WHERE b.IS_DELETED = 0
 AND b.ORDER_ID    = #{orderId} 
 AND b.ITEM_TYPE   = #{itemType} 
 AND b.OPERATOR_ID = #{operatorId} 
 AND b.RECORD_TIME >= #{startDate} 
 AND b.RECORD_TIME <  #{endDate}

SELECT NVL(SUM(CASE WHEN AMOUNT > 0 THEN AMOUNT ELSE 0 END), 0) AS "income",
       NVL(SUM(CASE WHEN AMOUNT < 0 THEN AMOUNT ELSE 0 END), 0) AS "refund",
       NVL(SUM(AMOUNT), 0) AS "net",
       COUNT(1) AS "txnCount"
  FROM BILL_ITEM
 WHERE IS_DELETED = 0
 AND OPERATOR_ID = #{operatorId} 
 AND RECORD_TIME >= #{startDate} 
 AND RECORD_TIME <  #{endDate}
